    "universal" => ["https://github.com/fthux/tick-rest-macos-dev/releases/download/v1.0.5/TickRest-1.0.5-universal.zip", "f5e93a42a67da23106ad3944e6e268007652da9e0dc7f38e4e9f4d77f8da3ebb"],
